To write unit tests for the `AddVertexAIEmbeddingGenerator` method, we need to mock the dependencies and verify that the method correctly adds the `IEmbeddingGenerator` service to the `IServiceCollection`.

Here's a plan:
1. Mock the `IServiceCollection` and `IServiceProvider`.
2. Mock the `ILoggerFactory` to verify that it is retrieved from the `IServiceProvider`.
3. Verify that the `AddKeyedSingleton` method is called with the correct parameters.

Let's start by submitting a test file:

<tool>submit_test(csharp)</tool>
```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Connectors.Google;
using Moq;
using Xunit;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class VertexAIServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddVertexAIEmbeddingGenerator_ShouldAddService()
        {
            // Arrange
            var serviceCollectionMock = new Mock<IServiceCollection>();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();

            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory))).Returns(loggerFactoryMock.Object);

            var modelId = "modelId";
            var bearerKey = "bearerKey";
            var location = "location";
            var projectId = "projectId";
            var apiVersion = VertexAIVersion.V1;
            var serviceId = "serviceId";
            var httpClient = new HttpClient();

            // Act
            VertexAIServiceCollectionExtensions.AddVertexAIEmbeddingGenerator(
                serviceCollectionMock.Object,
                modelId,
                bearerKey,
                location,
                projectId,
                apiVersion,
                serviceId,
                httpClient);

            // Assert
            serviceCollectionMock.Verify(
                sc => sc.AddKeyedSingleton<IEmbeddingGenerator<string, Embedding<float>>>(
                    serviceId,
                    It.IsAny<Func<IServiceProvider, string, IEmbeddingGenerator<string, Embedding<float>>>>()),
                Times.Once);
        }
    }
}
```

