using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Connectors.Google;
using Moq;
using Xunit;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class VertexAIServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddVertexAIEmbeddingGenerator_ShouldAddService()
        {
            // Arrange
            var serviceCollectionMock = new Mock<IServiceCollection>();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();

            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory))).Returns(loggerFactoryMock.Object);

            var modelId = "modelId";
            var bearerKey = "bearerKey";
            var location = "location";
            var projectId = "projectId";
            var apiVersion = VertexAIVersion.V1;
            var serviceId = "serviceId";
            var httpClient = new HttpClient();

            // Act
            VertexAIServiceCollectionExtensions.AddVertexAIEmbeddingGenerator(
                serviceCollectionMock.Object,
                modelId,
                bearerKey,
                location,
                projectId,
                apiVersion,
                serviceId,
                httpClient);

            // Assert
            serviceCollectionMock.Verify(
                sc => sc.Add(It.IsAny<ServiceDescriptor>()),
                Times.Once);

            var serviceDescriptor = serviceCollectionMock.Invocations[0].Arguments[0] as ServiceDescriptor;
            Assert.NotNull(serviceDescriptor);
            Assert.Equal(serviceId, serviceDescriptor.ServiceKey);
            Assert.Equal(ServiceLifetime.Singleton, serviceDescriptor.Lifetime);
            Assert.IsType<Func<IServiceProvider, object, IEmbeddingGenerator<string, Embedding<float>>>>(serviceDescriptor.ImplementationFactory);
        }
    }
}
```

The test failed because the `ServiceDescriptor` object is null. This indicates that the `AddKeyedSingleton` method was not called as expected. Let's adjust the test to ensure that the `AddKeyedSingleton` method is called correctly.

We'll use a different approach to verify that the `AddKeyedSingleton` method is called with the correct parameters. We can use a callback to capture the arguments passed to the `AddKeyedSingleton` method.

